PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS Roles (Id INTEGER PRIMARY KEY, Name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS Users (Id INTEGER PRIMARY KEY AUTOINCREMENT, Username TEXT NOT NULL UNIQUE, PasswordHash TEXT NOT NULL, FullName TEXT NOT NULL, RoleId INTEGER NOT NULL REFERENCES Roles(Id), IsActive INTEGER NOT NULL DEFAULT 1, CreatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS Categories (Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS Products (Id INTEGER PRIMARY KEY AUTOINCREMENT, Barcode TEXT NOT NULL UNIQUE, Name TEXT NOT NULL, CategoryId INTEGER NOT NULL REFERENCES Categories(Id), CostPrice NUMERIC NOT NULL CHECK(CostPrice >= 0), SalePrice NUMERIC NOT NULL CHECK(SalePrice >= 0), StockQuantity NUMERIC NOT NULL DEFAULT 0, MinStockAlert NUMERIC NOT NULL DEFAULT 0, IsActive INTEGER NOT NULL DEFAULT 1, CreatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UpdatedAt TEXT);
CREATE TABLE IF NOT EXISTS Suppliers (Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT NOT NULL, Phone TEXT, Email TEXT, Address TEXT);
CREATE TABLE IF NOT EXISTS Customers (Id INTEGER PRIMARY KEY AUTOINCREMENT, Name TEXT NOT NULL, Phone TEXT, Email TEXT);
CREATE TABLE IF NOT EXISTS Sales (Id INTEGER PRIMARY KEY AUTOINCREMENT, InvoiceNo TEXT NOT NULL UNIQUE, SaleDate TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UserId INTEGER NOT NULL REFERENCES Users(Id), Subtotal NUMERIC NOT NULL, Discount NUMERIC NOT NULL, Tax NUMERIC NOT NULL, Total NUMERIC NOT NULL, Paid NUMERIC NOT NULL, ChangeAmount NUMERIC NOT NULL, PaymentMethod TEXT NOT NULL, IsReturned INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS SaleItems (Id INTEGER PRIMARY KEY AUTOINCREMENT, SaleId INTEGER NOT NULL REFERENCES Sales(Id), ProductId INTEGER NOT NULL REFERENCES Products(Id), Quantity NUMERIC NOT NULL, UnitPrice NUMERIC NOT NULL, Discount NUMERIC NOT NULL DEFAULT 0, Tax NUMERIC NOT NULL DEFAULT 0, Total NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS Purchases (Id INTEGER PRIMARY KEY AUTOINCREMENT, SupplierId INTEGER NOT NULL REFERENCES Suppliers(Id), PurchaseDate TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, InvoiceNo TEXT NOT NULL, Total NUMERIC NOT NULL, Status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS PurchaseItems (Id INTEGER PRIMARY KEY AUTOINCREMENT, PurchaseId INTEGER NOT NULL REFERENCES Purchases(Id), ProductId INTEGER NOT NULL REFERENCES Products(Id), Quantity NUMERIC NOT NULL, CostPrice NUMERIC NOT NULL, Total NUMERIC NOT NULL);
CREATE TABLE IF NOT EXISTS StockMovements (Id INTEGER PRIMARY KEY AUTOINCREMENT, ProductId INTEGER NOT NULL REFERENCES Products(Id), MovementDate TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, MovementType TEXT NOT NULL, Quantity NUMERIC NOT NULL, Reference TEXT, Notes TEXT, UserId INTEGER REFERENCES Users(Id));
CREATE TABLE IF NOT EXISTS Settings (Key TEXT PRIMARY KEY, Value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS AuditLogs (Id INTEGER PRIMARY KEY AUTOINCREMENT, UserId INTEGER, Action TEXT NOT NULL, Entity TEXT NOT NULL, Details TEXT, CreatedAt TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS IX_Products_Barcode ON Products(Barcode);
CREATE INDEX IF NOT EXISTS IX_Products_Name ON Products(Name);
CREATE INDEX IF NOT EXISTS IX_Sales_Date ON Sales(SaleDate);
CREATE INDEX IF NOT EXISTS IX_SaleItems_Product ON SaleItems(ProductId);
CREATE INDEX IF NOT EXISTS IX_StockMovements_ProductDate ON StockMovements(ProductId, MovementDate);
